-- Little One Store: schema + security + seed
create table if not exists public.products (
  id text primary key,
  sort int not null default 100,
  category text not null,
  price_czk numeric not null,
  old_price_czk numeric,
  rating numeric not null default 4.8,
  reviews int not null default 0,
  emoji text not null default '🧸',
  gradient text,
  sizes jsonb not null default '[]',
  ages jsonb not null default '[]',
  colors jsonb not null default '[]',
  badge text,
  featured boolean not null default false,
  best_seller boolean not null default false,
  seasonal boolean not null default false,
  is_new boolean not null default false,
  hidden boolean not null default false,
  in_stock boolean not null default true,
  name_cs text, name_en text, name_uk text,
  desc_cs text, desc_en text, desc_uk text,
  material_cs text, material_en text, material_uk text,
  updated_at timestamptz not null default now()
);

create table if not exists public.site_settings (
  key text primary key,
  value jsonb not null
);

alter table public.products enable row level security;
alter table public.site_settings enable row level security;

drop policy if exists "public read visible products" on public.products;
create policy "public read visible products" on public.products
  for select using (hidden = false or auth.role() = 'authenticated');

drop policy if exists "admin write products" on public.products;
create policy "admin write products" on public.products
  for all using (auth.role() = 'authenticated') with check (auth.role() = 'authenticated');

drop policy if exists "public read settings" on public.site_settings;
create policy "public read settings" on public.site_settings
  for select using (true);

drop policy if exists "admin write settings" on public.site_settings;
create policy "admin write settings" on public.site_settings
  for all using (auth.role() = 'authenticated') with check (auth.role() = 'authenticated');

insert into public.site_settings (key, value)
  values ('shipping', '{"shipping_czk": 90, "free_over_czk": 2000}')
  on conflict (key) do nothing;

insert into storage.buckets (id, name, public)
  values ('product-images', 'product-images', true)
  on conflict (id) do nothing;

drop policy if exists "public read product images" on storage.objects;
create policy "public read product images" on storage.objects
  for select using (bucket_id = 'product-images');

drop policy if exists "admin upload product images" on storage.objects;
create policy "admin upload product images" on storage.objects
  for insert with check (bucket_id = 'product-images' and auth.role() = 'authenticated');

drop policy if exists "admin update product images" on storage.objects;
create policy "admin update product images" on storage.objects
  for update using (bucket_id = 'product-images' and auth.role() = 'authenticated');

drop policy if exists "admin delete product images" on storage.objects;
create policy "admin delete product images" on storage.objects
  for delete using (bucket_id = 'product-images' and auth.role() = 'authenticated');

insert into public.products
