   sizes, ages, colors, badge, featured, best_seller, seasonal, is_new, hidden, in_stock,
   name_cs, name_en, name_uk, desc_cs, desc_en, desc_uk, material_cs, material_en, material_uk)
values
('girls-summer-set', 10, 'girls', 349, null, 4.9, 41, '🎀', 'linear-gradient(140deg, #ffe3ec 0%, #ffc9d8 60%, #ffb6c8 100%)', '["6-9m", "9-12m", "12-18m", "18-24m"]'::jsonb, '["6-12m", "12-24m"]'::jsonb, '[{"name": "Pink", "hex": "#f7a8c4", "images": ["/products/girls-summer-set/pink-1.jpg", "/products/girls-summer-set/pink-2.jpg", "/products/girls-summer-set/pink-3.jpg", "/products/girls-summer-set/pink-4.jpg", "/products/girls-summer-set/pink-5.jpg"]}, {"name": "Peach Pink", "hex": "#f5bfae", "images": ["/products/girls-summer-set/peachpink-1.jpg", "/products/girls-summer-set/peachpink-2.jpg", "/products/girls-summer-set/peachpink-3.jpg", "/products/girls-summer-set/peachpink-4.jpg", "/products/girls-summer-set/peachpink-5.jpg"]}, {"name": "Dark Pink", "hex": "#e0729a", "images": ["/products/girls-summer-set/darkpink-1.jpg", "/products/girls-summer-set/darkpink-2.jpg", "/products/girls-summer-set/darkpink-3.jpg", "/products/girls-summer-set/darkpink-4.jpg", "/products/girls-summer-set/darkpink-5.jpg"]}]'::jsonb, 'New', true, false, true, true, false, true, 'Dívčí letní set – tričko a šortky', 'Girls Summer Set – Tee & Shorts', 'Літній комплект для дівчинки – футболка та шорти', 'Lehký a pohodlný letní komplet ze 100% bavlny, který zajistí maximální komfort i během horkých dnů. Souprava obsahuje růžové tričko s ozdobnou aplikací mašle a pruhované šortky s pružným pasem. Ideální na procházky, hraní i každodenní nošení.', 'A light and comfy summer set in 100% cotton that keeps little ones cool on hot days. The set pairs a pink tee with a decorative bow appliqué and striped shorts with an elastic waist — perfect for walks, play and everyday wear.', 'Легкий і зручний літній комплект зі 100% бавовни, що забезпечує максимальний комфорт навіть у спекотні дні. До набору входить рожева футболка з декоративним бантиком і смугасті шорти з еластичним поясом. Ідеально для прогулянок, ігор і щоденного носіння.', '100 % bavlna, měkká a prodyšná', '100% cotton, soft and breathable', null),
('girls-flower-set', 20, 'girls', 329, null, 4.8, 32, '🌸', 'linear-gradient(140deg, #ffe3ec 0%, #ffc9d8 60%, #ffb6c8 100%)', '["9-12m", "12-18m", "18-24m"]'::jsonb, '["6-12m", "12-24m"]'::jsonb, '[{"name": "Pink", "hex": "#f2b7c6", "images": ["/products/girls-flower-set/pink-1.jpg", "/products/girls-flower-set/pink-2.jpg", "/products/girls-flower-set/pink-3.jpg", "/products/girls-flower-set/pink-4.jpg", "/products/girls-flower-set/pink-5.jpg"]}]'::jsonb, null, true, false, false, false, false, true, 'Dívčí souprava – mikina a kalhoty', 'Girls Set – Sweatshirt & Pants', 'Комплект для дівчинки – світшот і штани', 'Elegantní a pohodlná souprava z 95 % bavlny a 5 % elastanu. Komplet tvoří mikina s dlouhým rukávem, ozdobným krajkovým límečkem a jemným květinovým vzorem spolu s pohodlnými kalhotami s pružným pasem. Měkká, příjemná na dotek a zároveň pružná.', 'An elegant, comfortable two-piece set in 95% cotton and 5% elastane. A long-sleeve top with a delicate lace collar and fine floral print comes with soft pants with an elastic waist — gentle to the touch with just the right stretch.', null, '95 % bavlna, 5 % elastan', '95% cotton, 5% elastane', '95 % бавовна, 5 % еластан'),
('bunny-3piece-set', 30, 'baby', 399, null, 4.9, 56, '🐰', 'linear-gradient(140deg, #f7eede 0%, #efe0c8 60%, #e6d2b2 100%)', '["9-12m", "12-18m"]'::jsonb, '["6-12m", "12-24m"]'::jsonb, '[{"name": "Beige", "hex": "#e6d3b8", "images": ["/products/bunny-3piece-set/beige-1.jpg", "/products/bunny-3piece-set/beige-2.jpg", "/products/bunny-3piece-set/beige-3.jpg", "/products/bunny-3piece-set/beige-4.jpg", "/products/bunny-3piece-set/beige-5.jpg"]}, {"name": "Pink", "hex": "#f4b9c8", "images": ["/products/bunny-3piece-set/pink-1.jpg", "/products/bunny-3piece-set/pink-2.jpg", "/products/bunny-3piece-set/pink-3.jpg", "/products/bunny-3piece-set/pink-4.jpg", "/products/bunny-3piece-set/pink-5.jpg"]}]'::jsonb, 'Bestseller', true, true, false, false, false, true, 'Dětská 3dílná souprava se zajíčkem', 'Bunny 3-Piece Set with Vest', 'Дитячий комплект із 3 частин із зайчиком', 'Stylová a pohodlná 3dílná souprava pro nejmenší, ideální na jaro, podzim i chladnější letní dny. Komplet obsahuje mikinu s roztomilým motivem zajíčka, pohodlné bavlněné kalhoty a lehce zateplenou vestu s kapucí. K dispozici v béžové a růžové barvě.', 'A stylish 3-piece set for the littlest ones — ideal for spring, autumn and cooler summer days. It includes a sweatshirt with an adorable bunny motif, soft cotton pants and a lightly insulated hooded vest. Available in beige and pink.', null, 'Mikina a kalhoty 100 % bavlna · vesta 50 % bavlna, 50 % polyester', 'Sweatshirt & pants 100% cotton · vest 50% cotton, 50% polyester', 'Світшот і штани 100 % бавовна · жилетка 50 % бавовна, 50 % поліестер'),
('cotton-pants-2pack', 40, 'baby', 199, null, 4.7, 63, '🦁', 'linear-gradient(140deg, #f7eede 0%, #efe0c8 60%, #e6d2b2 100%)', '["3-6m", "6-9m", "9-12m", "12-18m"]'::jsonb, '["0-6m", "6-12m", "12-24m"]'::jsonb, '[{"name": "Safari", "hex": "#d9c39a", "images": ["/products/cotton-pants-2pack/safari-1.jpg", "/products/cotton-pants-2pack/safari-2.jpg", "/products/cotton-pants-2pack/safari-3.jpg", "/products/cotton-pants-2pack/safari-4.jpg", "/products/cotton-pants-2pack/safari-5.jpg"]}]'::jsonb, null, false, true, false, false, false, true, 'Dětské bavlněné kalhoty – 2 ks', 'Cotton Baby Pants – 2-Pack', 'Дитячі бавовняні штани – 2 шт.', 'Pohodlné dětské kalhoty ze 100% bavlny pro každodenní nošení. Sada obsahuje 2 kusy – jedny s veselým motivem safari zvířátek a jedny jednobarevné s potiskem zebry. Díky pružnému pasu se snadno oblékají a perfektně padnou.', 'Comfy 100% cotton baby pants for all-day wear. The pack contains two pairs — one with a cheerful safari-animal print and one plain with a zebra motif. The elastic waist makes dressing quick and easy.', 'Зручні дитячі штани зі 100% бавовни для щоденного носіння. У наборі 2 штуки — одні з веселим сафарі-принтом, другі однотонні із зеброю. Завдяки еластичному поясу легко вдягаються та чудово сидять.', '100 % bavlna, měkká a prodyšná', '100% cotton, soft and breathable', null),
('bear-3piece-set', 50, 'boys', 399, null, 4.9, 48, '🐻', 'linear-gradient(140deg, #ddefff 0%, #c2ddff 60%, #aacdf5 100%)', '["6-9m", "9-12m", "12-18m"]'::jsonb, '["6-12m", "12-24m"]'::jsonb, '[{"name": "Blue", "hex": "#a9c8ea", "images": ["/products/bear-3piece-set/blue-1.jpg", "/products/bear-3piece-set/blue-2.jpg", "/products/bear-3piece-set/blue-3.jpg", "/products/bear-3piece-set/blue-4.jpg", "/products/bear-3piece-set/blue-5.jpg"]}, {"name": "Grey", "hex": "#b9bdc4", "images": ["/products/bear-3piece-set/grey-1.jpg", "/products/bear-3piece-set/grey-2.jpg", "/products/bear-3piece-set/grey-3.jpg", "/products/bear-3piece-set/grey-4.jpg", "/products/bear-3piece-set/grey-5.jpg"]}]'::jsonb, 'Bestseller', true, true, false, false, false, true, 'Chlapecká 3dílná souprava s medvídkem', 'Boys Bear 3-Piece Set', 'Комплект для хлопчика з ведмедиком (3 частини)', 'Pohodlná a stylová 3dílná souprava pro malé kluky, ideální na jaro, podzim i chladnější dny. Součástí kompletu je mikina s roztomilým motivem medvídka, pohodlné bavlněné kalhoty a lehce zateplená vesta s kapucí. K dispozici v modré a šedé barvě.', 'A comfortable, stylish 3-piece set for little boys — great for spring, autumn and chilly days. Includes a sweatshirt with a cute teddy-bear motif, soft cotton pants and a lightly insulated hooded vest. Available in blue and grey.', 'Зручний і стильний комплект із 3 частин для маленьких хлопчиків — чудовий для весни, осені та прохолодних днів. До набору входить світшот із милим ведмедиком, зручні бавовняні штани та легка утеплена жилетка з капюшоном. Доступний у блакитному та сірому кольорах.', 'Mikina a kalhoty 100 % bavlna · vesta 50 % bavlna, 50 % polyester', 'Sweatshirt & pants 100% cotton · vest 50% cotton, 50% polyester', 'Світшот і штани 100 % бавовна · жилетка 50 % бавовна, 50 % поліестер'),
